+function fmtCost(n) {
+  if (n === null || n === undefined || Number.isNaN(Number(n))) return '—';
+  if (n === 0) return '$0.00';
+  if (Math.abs(n) < 0.01) return `$${Number(n).toFixed(4)}`;
+  return `$${Number(n).toFixed(2)}`;
+}
+
+function escapeHtml(value) {
+  return String(value ?? '').replace(/[&<>"]/g, char => ({
+    '&': '&amp;',
+    '<': '&lt;',
+    '>': '&gt;',
+    '"': '&quot;',
+  }[char]));
+}
+
+function sanitizeColor(value, fallback = '#64748B') {
+  const raw = String(value ?? '').trim();
+  return /^#(?:[0-9a-fA-F]{3}|[0-9a-fA-F]{6}|[0-9a-fA-F]{8})$/.test(raw) ? raw : fallback;
+}
+
+function clearNode(node) {
+  node.replaceChildren();
+}
+
+function makeTableEmptyState(tbody, colspan, message) {
+  clearNode(tbody);
+  const row = document.createElement('tr');
+  const cell = document.createElement('td');
+  cell.colSpan = colspan;
+  cell.style.textAlign = 'center';
+  cell.style.color = 'var(--text-tertiary)';
+  cell.style.padding = '40px';
+  cell.textContent = message;
+  row.appendChild(cell);
+  tbody.appendChild(row);
+}
+
+function createToolPill({ tool, toolColor, sourcePath }) {
+  const pill = document.createElement('span');
+  pill.className = 'tool-pill';
+  pill.style.borderColor = sanitizeColor(toolColor, '#64748B');
+  pill.style.color = sanitizeColor(toolColor, '#9aa0a6');
+  pill.title = String(sourcePath || '');
+  pill.textContent = tool || 'OpenCode';
+  return pill;
+}
+
+function createLegendDot(color) {
+  const dot = document.createElement('span');
+  dot.className = 'legend-dot';
+  dot.style.background = sanitizeColor(color, '#64748B');
+  return dot;
+}
+
+function setCardMeta(id, visible, detail = '') {
+  const el = document.getElementById(id);
+  if (!el) return;
+  const detailText = String(detail || '');
+  const tooltipId = `${id}-tooltip`;
+  el.innerHTML = `
+    <span class="meta-main">${escapeHtml(visible)}</span>
+    ${detailText ? `
+      <span class="meta-info-wrap">
+        <button
+          type="button"
+          class="meta-info"
+          aria-label="More information"
+          aria-expanded="false"
+          aria-describedby="${escapeHtml(tooltipId)}"
+        >i</button>
+        <span class="meta-tooltip" id="${escapeHtml(tooltipId)}" role="tooltip">${escapeHtml(detailText)}</span>
+      </span>
+    ` : ''}
+  `;
+  bindMetaInfoInteractions(el);
+}
+
+function closeMetaInfo(exceptWrap = null) {
+  document.querySelectorAll('.meta-info-wrap.is-open').forEach(wrap => {
+    if (wrap === exceptWrap) return;
+    wrap.classList.remove('is-open');
+    wrap.querySelector('.meta-info')?.setAttribute('aria-expanded', 'false');
+  });
+}
+
+function bindMetaInfoInteractions(root = document) {
+  root.querySelectorAll('.meta-info-wrap .meta-info').forEach(button => {
+    if (button.dataset.bound === 'true') return;
+    button.dataset.bound = 'true';
+
+    button.addEventListener('click', event => {
+      event.preventDefault();
+      event.stopPropagation();
+      const wrap = button.closest('.meta-info-wrap');
+      const willOpen = !wrap.classList.contains('is-open');
+      closeMetaInfo(wrap);
+      wrap.classList.toggle('is-open', willOpen);
+      button.setAttribute('aria-expanded', willOpen ? 'true' : 'false');
